// Program slots and immutable plan snapshots extend the original girya-v1 data.
const slotKeys=['A','B','C'];
const slotLabels={A:'А',B:'Б',C:'В'};
if(!db.programs){db.programs={A:structuredClone(db.program),B:[{name:'Гоблет-присед',sets:3,weight:16,reps:12,bells:1},{name:'Жим гири стоя',sets:3,weight:16,reps:10,bells:1},{name:'Тяга гири в наклоне',sets:3,weight:16,reps:12,bells:1}],C:[{name:'Махи гирей',sets:4,weight:16,reps:15,bells:1},{name:'Тяга гири в наклоне',sets:3,weight:16,reps:12,bells:1}]};db.activeProgram='A'}
db.activeProgram=slotKeys.includes(db.activeProgram)?db.activeProgram:'A';
db.draftPrograms=db.draftPrograms||{};
Object.defineProperty(db,'program',{configurable:true,enumerable:true,get(){return db.programs[db.activeProgram]},set(value){db.programs[db.activeProgram]=value}});
save();
const baseDraft=draft,baseProgram=program,baseWorkout=workout,baseBind=bind,baseFinish=finishIron;
let editingSlot=db.activeProgram,metric='tonnage';
function numberLabel(n){return Number(n).toLocaleString('ru-RU',{maximumFractionDigits:1})}
function slotTabs(key,attr){return `<div class="program-tabs" role="group" aria-label="Программы по дням">${slotKeys.map(k=>`<button type="button" class="${key===k?'primary':'secondary'}" ${attr}="${k}" aria-pressed="${key===k}">Тренировка ${slotLabels[k]}</button>`).join('')}</div>`}
draft=function(){const fresh=!db.drafts[selected];const ex=baseDraft();if(fresh){ex.forEach(e=>e.sets.forEach(s=>{s.plan={weight:s.weight,reps:s.reps,bells:s.bells};s.effort=null}));db.draftPrograms[selected]=db.activeProgram;save()}return ex};
function draftSlot(){draft();return db.draftPrograms[selected]||null}
function chooseWorkout(k){if(!slotKeys.includes(k))return;if(draftSlot()===k)return;if(completed(draft())||db.sessions.some(s=>s.date===selected)){toast('В этот день уже есть выполненные подходы. Выбери другую дату для новой программы.');return}stopRest();db.activeProgram=k;delete db.drafts[selected];delete db.draftPrograms[selected];draft();save();render()}
workout=function(){let html=baseWorkout(),n=nextApproach(),slot=draftSlot();const tabs=`<div class="workout-program"><div class="between"><span class="muted">Программа на выбранную дату${slot?'':' · прежняя тренировка'}</span><span class="muted">А / Б / В</span></div>${slotTabs(slot,'data-workout-slot')}<p class="muted">Программу можно менять до первого выполненного подхода. Один день — одна тренировка.</p></div>`;html=html.replace('<div class="iron-grid">',tabs+'<div class="iron-grid">');if(n){const p=n.s.plan;const info=`<div class="plan-fact"><span>План: <b>${p?`${numberLabel(p.weight)} кг × ${p.reps} × ${p.bells} гир.`:'не записан в прежней версии'}</b></span><span>Ниже — фактический результат</span></div>`;html=html.replace('<div class="focus-numbers">',info+'<div class="focus-numbers">');const effort=`<label class="effort-label">Насколько тяжело?<select id="set-effort" aria-label="Сложность текущего подхода"><option value="">Не указывать</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${n.s.effort===i+1?'selected':''}>${i+1} / 10${i===0?' · очень легко':i===9?' · предельно тяжело':''}</option>`).join('')}</select></label>`;html=html.replace('<div class="focus-footer">',effort+'<div class="focus-footer">')}return html};
program=function(){const prior=db.activeProgram;db.activeProgram=editingSlot;const html=baseProgram();db.activeProgram=prior;return `<div class="program-editor">${slotTabs(editingSlot,'data-edit-slot')}<p class="muted">А — твоя исходная программа. Б и В — редактируемые заготовки. Настрой их под свой план.</p>${html.replace('Программа тренировок</h2>',`Тренировка ${slotLabels[editingSlot]}</h2>`)}<button class="secondary" id="use-program">Выбрать ${slotLabels[editingSlot]} для тренировки</button></div>`};
function withEditingSlot(fn){const prior=db.activeProgram;db.activeProgram=editingSlot;try{return fn()}finally{db.activeProgram=prior;save()}}
function captureEditor(){const form=$('#program-form');if(!form)return true;if(!form.reportValidity())return false;withEditingSlot(()=>captureProgram());return true}
const originalImport=importProgram;
importProgram=async function(event){const prior=db.activeProgram;db.activeProgram=editingSlot;try{await originalImport(event)}finally{db.activeProgram=prior;save()}};
finishIron=function(){if(!completed(draft()))return baseFinish();baseFinish();const session=db.sessions.find(s=>s.date===selected);if(session){session.programKey=draftSlot();save()}};

function valuesForExercise(session,name){return session.exercises.filter(e=>e.name===name).flatMap(e=>e.sets.filter(s=>s.done).map(s=>({...s,bells:s.bells||1})))}
function metricValue(sets,key){if(key==='weight')return Math.max(0,...sets.map(s=>s.weight));if(key==='reps')return sets.reduce((a,s)=>a+s.reps,0);if(key==='sets')return sets.length;return sets.reduce((a,s)=>a+s.weight*s.reps*s.bells,0)}
const metricNames={tonnage:'Тоннаж',weight:'Рабочий вес',reps:'Повторения',sets:'Подходы'};
const metricUnits={tonnage:'кг',weight:'кг одной гири',reps:'повт.',sets:'подх.'};
function progressChart(){const now=new Date(),points=Array.from({length:period},(_,i)=>{let end=new Date(now);end.setDate(end.getDate()-(period-1-i)*7);let start=new Date(end);start.setDate(start.getDate()-6);start.setHours(0,0,0,0);end.setHours(23,59,59,999);const sets=db.sessions.filter(s=>{const d=new Date(s.date+'T12:00:00');return d>=start&&d<=end}).flatMap(s=>valuesForExercise(s,graphExercise));return {v:metricValue(sets,metric),label:end.toLocaleDateString('ru-RU',{day:'numeric',month:'short'})}}),max=Math.max(1,...points.map(p=>p.v)),coordinates=points.map((p,i)=>`${40+i*320/(period-1)},${115-p.v/max*90}`);return `<svg class="chart expanded-chart" viewBox="0 0 390 155" role="img" aria-label="${metricNames[metric]} по неделям">${[25,70,115].map((y,i)=>`<line x1="40" y1="${y}" x2="360" y2="${y}"/><text x="1" y="${y+3}">${numberLabel(max*(1-i/2))}</text>`).join('')}<path d="M${coordinates.join(' L')}" fill="none" stroke-width="2.5"/>${coordinates.map((c,i)=>{const [x,y]=c.split(',');return `<circle cx="${x}" cy="${y}" r="3.5"><title>${esc(points[i].label)}: ${points[i].v}</title></circle>`}).join('')}${points.map((p,i)=>i%2===0||i===period-1?`<text x="${40+i*320/(period-1)}" y="145" text-anchor="middle">${esc(p.label)}</text>`:'').join('')}</svg>`}
progress=function(){const names=[...new Set([...slotKeys.flatMap(k=>db.programs[k].map(e=>e.name)),...db.sessions.flatMap(s=>s.exercises.map(e=>e.name))])];if(!names.includes(graphExercise))graphExercise=names[0]||'';const history=db.sessions.filter(s=>valuesForExercise(s,graphExercise).length).sort((a,b)=>b.date.localeCompare(a.date)),latest=history[0],previous=history[1],allSets=history.flatMap(s=>valuesForExercise(s,graphExercise)),best=allSets.reduce((a,s)=>!a||s.weight*s.reps*s.bells>a.weight*a.reps*a.bells?s:a,null);const latestSets=latest?valuesForExercise(latest,graphExercise):[],prevSets=previous?valuesForExercise(previous,graphExercise):[];const delta=previous?metricValue(latestSets,metric)-metricValue(prevSets,metric):null;
return title('Видеть результат','Твой прогресс','Вес, повторения и объём работы — по каждому упражнению.')+`<div class="card"><div class="progress-filters"><label class="field">Упражнение<select id="graph-ex" aria-label="Упражнение">${names.map(n=>`<option ${n===graphExercise?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field">Период<select id="period" aria-label="Период"><option value="4" ${period===4?'selected':''}>4 недели</option><option value="8" ${period===8?'selected':''}>8 недель</option></select></label></div><div class="metric-tabs" role="group" aria-label="Показатель прогресса">${Object.entries(metricNames).map(([k,v])=>`<button class="${metric===k?'primary':'secondary'}" data-metric="${k}" aria-pressed="${metric===k}">${v}</button>`).join('')}</div><div class="between"><h2>${metricNames[metric]} по неделям</h2><span class="muted">${metricUnits[metric]}</span></div>${progressChart()}<p class="muted">${metric==='weight'?'Максимальный вес одной гири среди выполненных подходов за неделю.':'Сумма выполненных '+(metric==='tonnage'?'вес × повторения × количество гирь':metric==='reps'?'повторений':'подходов')+' за неделю.'}</p>${!history.length?'<p class="muted">Сохрани тренировку с этим упражнением — появятся результаты.</p>':''}</div><div class="progress-records"><div class="card"><span class="muted">Личный рекорд · вес одной гири</span><h2>${allSets.length?numberLabel(metricValue(allSets,'weight'))+' кг':'—'}</h2><p class="muted">За всю сохранённую историю</p></div><div class="card"><span class="muted">Лучший подход · по тоннажу</span><h2>${best?`${numberLabel(best.weight)} × ${best.reps}`:'—'}</h2><p class="muted">${best?`${best.bells} гир. · ${numberLabel(best.weight*best.reps*best.bells)} кг тоннажа`:'Пока нет выполненных подходов'}</p></div><div class="card"><span class="muted">К предыдущей тренировке · ${metricNames[metric].toLowerCase()}</span><h2>${delta===null?'—':`${delta>0?'+':''}${numberLabel(delta)} ${metric==='sets'?'подх.':metric==='reps'?'повт.':'кг'}`}</h2><p class="muted">${previous?`${esc(previous.date)} → ${esc(latest.date)} · одно упражнение`:'Нужны две тренировки с этим упражнением'}</p></div></div><div class="card"><h2>План и факт · ${esc(graphExercise)}</h2><p class="muted">Последние 8 тренировок. Повторения одной рукой считаются суммарно на обе руки.</p>${history.length?history.slice(0,8).map(session=>`<details class="session-detail"><summary>${new Date(session.date+'T12:00:00').toLocaleDateString('ru-RU')} · ${session.programKey?'Тренировка '+slotLabels[session.programKey]:'Прежняя программа'}<b>${numberLabel(metricValue(valuesForExercise(session,graphExercise),'tonnage'))} кг</b></summary><div class="table-scroll"><table><thead><tr><th>Подход</th><th>План: кг × повт. × гири</th><th>Факт: кг × повт. × гири</th><th>Сложность</th></tr></thead><tbody>${valuesForExercise(session,graphExercise).map((s,i)=>`<tr><td>${i+1}</td><td>${s.plan?`${s.plan.weight} × ${s.plan.reps} × ${s.plan.bells}`:'Не записан'}</td><td>${s.weight} × ${s.reps} × ${s.bells}</td><td>${s.effort?s.effort+'/10':'—'}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):'<div class="empty">История появится после сохранения тренировки.</div>'}</div>`};

bind=function(){
  // Existing handlers use db.program; select the editor slot only while binding.
  const prior=db.activeProgram;if(page==='program')db.activeProgram=editingSlot;
  try{baseBind()}finally{db.activeProgram=prior}
  document.querySelectorAll('[data-workout-slot]').forEach(b=>b.onclick=()=>chooseWorkout(b.dataset.workoutSlot));
  if(page==='workout'){
    const n=nextApproach();if(n&&$('#set-effort'))$('#set-effort').onchange=e=>{n.s.effort=e.target.value?+e.target.value:null;save()};
    // Snapshot added approaches too; never invent plans for pre-upgrade rows.
    document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{let e=draft()[b.dataset.add],last=e.sets.at(-1);e.sets.push({weight:last.weight,reps:last.reps,bells:last.bells,done:false,effort:null,plan:last.plan?structuredClone(last.plan):null});save();render()});
    document.querySelectorAll('.exercise').forEach((article,i)=>{const e=draft()[i];article.querySelectorAll('.set').forEach((row,j)=>{const p=e.sets[j].plan;const label=document.createElement('div');label.className='journal-plan';label.textContent=p?`План ${p.weight} кг × ${p.reps} × ${p.bells} гир.`:'План в прежней версии не записан';row.after(label)})});
  }
  if(page==='program'){
    const form=$('#program-form');form.onsubmit=e=>{e.preventDefault();if(captureEditor())toast('Тренировка '+slotLabels[editingSlot]+' сохранена')};
    document.querySelectorAll('[data-edit-slot]').forEach(b=>b.onclick=()=>{if(!captureEditor())return;editingSlot=b.dataset.editSlot;render()});
    $('#program-add').onclick=()=>{if(!captureEditor())return;db.programs[editingSlot].push({name:'Новое упражнение',sets:3,weight:16,reps:10,bells:1});save();render()};
    document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!captureEditor())return;const p=db.programs[editingSlot];if(p.length===1)return toast('Оставь хотя бы одно упражнение');p.splice(+b.dataset.remove,1);save();render()});
    $('#use-program').onclick=()=>{if(!captureEditor())return;chooseWorkout(editingSlot);navigate('workout')};
    form.querySelectorAll('input').forEach(input=>input.addEventListener('change',()=>{if(form.checkValidity())captureEditor()}));
  }
  if(page==='progress')document.querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{metric=b.dataset.metric;render()});
};
render();

